/**
 * El texto de los Términos y Condiciones, versión 3.2.
 *
 * **Transcripción literal del documento legal** (`INVICTO_Terminos_y_Condiciones
 * _v3.2_FINAL.docx`, 20 de octubre de 2026). Se genera desde ese archivo y no se
 * edita a mano: si cambia el documento, se vuelve a generar.
 *
 * Esta es la copia **descargable y permanente** que exige la Cláusula 1.4, la
 * que el usuario tiene que poder leer desde `www.invictoapp.com.co` antes de
 * registrarse. El mismo texto vive en la app
 * (`InvictoApp/src/features/auth/constants/terms-content.ts`) y los dos salen
 * del mismo .docx — **si se actualiza uno hay que regenerar el otro**, o la
 * plataforma estaría exhibiendo dos versiones del contrato a la vez.
 */
export type TermsBlock =
  /** TÍTULO I. … — separador de nivel superior */
  | { kind: 'titulo'; text: string }
  /** CLÁUSULA 17. PROTOCOLO DE CONTACTO CON MENORES */
  | { kind: 'clausula'; num: string; text: string }
  /** ANEXO 2. TEXTOS DE ACEPTACIÓN Y AUTORIZACIÓN */
  | { kind: 'anexo'; num: string; text: string }
  /** Subtítulo dentro de un anexo: «A. Jugadores» */
  | { kind: 'sub'; text: string }
  /** 17.2 … — el número va aparte para poder alinearlo */
  | { kind: 'p'; num?: string; text: string }
  /** a) … dentro de una cláusula */
  | { kind: 'item'; num: string; text: string }
  /** Una definición de la Cláusula 3: término + significado */
  | { kind: 'def'; term: string; text: string }
  /** Una casilla del Anexo 2. Se pinta como texto, NO como casilla real */
  | { kind: 'check'; text: string }
  | { kind: 'tabla'; head: string[]; rows: string[][] };

export const TERMS_VERSION = 'Versión 3.2';
export const TERMS_UPDATED = '20 de octubre de 2026';

/**
 * El aviso del encabezado del documento. Va aparte porque el artículo 37 de la
 * Ley 1480 de 2011 pide que las cláusulas que limitan derechos se resalten, y
 * este párrafo es el que lo anuncia: se pinta destacado, no como un párrafo más.
 */
export const TERMS_LEAD =
  'LEA ATENTAMENTE ESTE DOCUMENTO ANTES DE USAR INVICTO. Estos Términos y '
  + 'Condiciones constituyen un contrato vinculante entre usted e INVICTO. Si usted '
  + 'es menor de dieciocho (18) años, no puede aceptarlos por sí mismo: su padre, '
  + 'madre o tutor legal debe hacerlo en su nombre a través de la Cuenta de '
  + 'Acudiente. Las cláusulas que limitan derechos o responsabilidades, regulan la '
  + 'renovación automática de suscripciones, los reembolsos, la suspensión de '
  + 'cuentas y la solución de controversias aparecen resaltadas en negrita, '
  + 'conforme al artículo 37 de la Ley 1480 de 2011.';

/**
 * El párrafo del Anexo 2.B: la autorización que otorga el padre, la madre o el
 * tutor legal de un Menor.
 *
 * Se pinta **destacado y aparte** aunque el Anexo 2 también aparezca dentro del
 * texto completo. Es lo único de este documento que un padre tiene que leer sin
 * excusa, y enterrado en el anexo de un documento de 95 cláusulas no lo lee
 * nadie.
 */
